#[rustfmt::skip]
fn conditional<A: IVm>() {
    check::<A>("truePicksConsequent", Any::conditional(true.to_any(), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("falsePicksAlternate", Any::conditional(false.to_any(), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("nullPicksAlternate", Any::conditional(Nullish::Null.to_any(), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("undefinedPicksAlternate", Any::conditional(Nullish::Undefined.to_any(), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("zeroPicksAlternate", Any::conditional((0f64).to_any(), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("nanPicksAlternate", Any::conditional((f64::NAN).to_any(), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("emptyStringPicksAlternate", Any::conditional(string_any(""), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("nonEmptyStringPicksConsequent", Any::conditional(string_any("a"), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("bigZeroPicksAlternate", Any::conditional(bigint_any(0), (1f64).to_any(), (2f64).to_any()), (2f64).to_any());
    check::<A>("bigNonZeroPicksConsequent", Any::conditional(bigint_any(5), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("emptyArrayPicksConsequent", Any::conditional(Array::default().to_any(), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("emptyObjectPicksConsequent", Any::conditional(Object::default().to_any(), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("functionPicksConsequent", Any::conditional(function_any(), (1f64).to_any(), (2f64).to_any()), (1f64).to_any());
    check::<A>("truePicksStringConsequent", Any::conditional(true.to_any(), string_any("yes"), string_any("no")), string_any("yes"));
    check::<A>("falsePicksBigAlternate", Any::conditional(false.to_any(), bigint_any(1), bigint_any(2)), bigint_any(2));
}

#[rustfmt::skip]
fn type_of<A: IVm>() {
    check::<A>("undefined", Any::type_of(Nullish::Undefined.to_any()), string_any("undefined"));
    check::<A>("null", Any::type_of(Nullish::Null.to_any()), string_any("object"));
    check::<A>("booleanTrue", Any::type_of(true.to_any()), string_any("boolean"));
    check::<A>("booleanFalse", Any::type_of(false.to_any()), string_any("boolean"));
    check::<A>("number", Any::type_of((2.3f64).to_any()), string_any("number"));
    check::<A>("numberNan", Any::type_of((f64::NAN).to_any()), string_any("number"));
    check::<A>("string", Any::type_of(string_any("a")), string_any("string"));
    check::<A>("stringEmpty", Any::type_of(string_any("")), string_any("string"));
    check::<A>("bigint", Any::type_of(bigint_any(5)), string_any("bigint"));
    check::<A>("bigintZero", Any::type_of(bigint_any(0)), string_any("bigint"));
    check::<A>("emptyArray", Any::type_of(Array::default().to_any()), string_any("object"));
    check::<A>("array", Any::type_of([(1f64).to_any(), (2f64).to_any()].to_array().to_any()), string_any("object"));
    check::<A>("emptyObject", Any::type_of(Object::default().to_any()), string_any("object"));
    check::<A>("object", Any::type_of([(string_key("a"), (1f64).to_any())].to_object().to_any()), string_any("object"));
    check::<A>("function", Any::type_of(function_any()), string_any("function"));
}

#[rustfmt::skip]
fn string_coercion<A: IVm>() {
    check::<A>("number", (123f64).to_any().to_string().map(|v| v.to_any()), string_any("123"));
    check::<A>("negativeNumber", (-456f64).to_any().to_string().map(|v| v.to_any()), string_any("-456"));
    check::<A>("zero", (0f64).to_any().to_string().map(|v| v.to_any()), string_any("0"));
    check::<A>("negativeZero", (-0f64).to_any().to_string().map(|v| v.to_any()), string_any("0"));
    check::<A>("infinity", (f64::INFINITY).to_any().to_string().map(|v| v.to_any()), string_any("Infinity"));
    check::<A>("negativeInfinity", (f64::NEG_INFINITY).to_any().to_string().map(|v| v.to_any()), string_any("-Infinity"));
    check::<A>("nan", (f64::NAN).to_any().to_string().map(|v| v.to_any()), string_any("NaN"));
    check::<A>("booleanTrue", true.to_any().to_string().map(|v| v.to_any()), string_any("true"));
    check::<A>("booleanFalse", false.to_any().to_string().map(|v| v.to_any()), string_any("false"));
    check::<A>("null", Nullish::Null.to_any().to_string().map(|v| v.to_any()), string_any("null"));
    check::<A>("undefined", Nullish::Undefined.to_any().to_string().map(|v| v.to_any()), string_any("undefined"));
    check::<A>("string", string_any("already").to_string().map(|v| v.to_any()), string_any("already"));
    check::<A>("bigint", bigint_any(123).to_string().map(|v| v.to_any()), string_any("123"));
    check::<A>("negativeBigint", bigint_any(-456).to_string().map(|v| v.to_any()), string_any("-456"));
    check::<A>("emptyArray", Array::default().to_any().to_string().map(|v| v.to_any()), string_any(""));
    check::<A>("singletonArray", [(1f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1"));
    check::<A>("array", [(1f64).to_any(), (2f64).to_any(), (3f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1,2,3"));
    check::<A>("nestedArray", [(1f64).to_any(), [(2f64).to_any(), (3f64).to_any()].to_array().to_any(), (4f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any("1,2,3,4"));
    check::<A>("arrayWithNullish", [Nullish::Null.to_any(), Nullish::Undefined.to_any(), (1f64).to_any()].to_array().to_any().to_string().map(|v| v.to_any()), string_any(",,1"));
    check::<A>("emptyObject", Object::default().to_any().to_string().map(|v| v.to_any()), string_any("[object Object]"));
    check::<A>("object", [(string_key("a"), (1f64).to_any())].to_object().to_any().to_string().map(|v| v.to_any()), string_any("[object Object]"));
}

